package org.zhbot.fossil_island_mahogany_timers;

import net.runelite.client.config.*;

import java.awt.*;

@ConfigGroup(FossilIslandMahoganyTimersConfig.group)
public interface FossilIslandMahoganyTimersConfig extends Config
{
	String group = "fossil-island-mahogany-timers";

	@ConfigItem(
			keyName = "notifyOnChop",
			name = "Notify on Chop",
			description = "Send a client notification when tree chopped.",
			position = 0
	)
	default Notification notifyOnChop()
	{
		return Notification.ON;
	}

	@ConfigItem(
			keyName = "notifyOnFull",
			name = "Notify on Full",
			description = "Send notification when inventory is full.",
			position = 1
	)
	default Notification notifyOnFull()
	{
		return Notification.ON;
	}

	@Alpha
	@ConfigItem(
			keyName = "progressColour",
			name = "Colour",
			description = "The colour for the progress pie chart.",
			position = 2
	)
	default Color progressColour()
	{
		return Color.GREEN;
	}
}

package org.zhbot.fossil_island_mahogany_timers;

import com.google.inject.Provides;
import javax.inject.Inject;

import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.coords.WorldArea;
import net.runelite.api.events.*;
import net.runelite.api.gameval.ObjectID;
import net.runelite.client.Notifier;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

import java.util.HashSet;
import java.util.Set;

@Slf4j
@PluginDescriptor(
	name = "Fossil Island Mahogany Timers",
	description = "A plugin to add respawn timers to the Fossil Island mahogany trees.",
	tags = {"fossil", "island", "farming", "hardwood", "mahogany"}
)
public class FossilIslandMahoganyTimersPlugin extends Plugin
{
	private static final WorldArea FOSSIL_ISLAND_HARDWOOD_AREA = new WorldArea(3695, 3789, 49, 53, 0);
	private static final Set<Integer> FOSSIL_ISLAND_HARDWOOD_PATCH_IDS = Set.of(
			ObjectID.FARMING_HARDWOOD_TREE_PATCH_1,
			ObjectID.FARMING_HARDWOOD_TREE_PATCH_2,
			ObjectID.FARMING_HARDWOOD_TREE_PATCH_3
		);
	private static final String INVENTORY_FULL_MESSAGE = "Your inventory is too full to hold any more mahogany logs.";

	@Inject
	private Client client;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private Notifier notifier;

	@Inject
	private FossilIslandMahoganyTimersConfig config;

	@Inject
	private FossilIslandMahoganyTimersOverlay overlay;

	@Getter
	private boolean inFossilIslandHardwoodArea = false;

	@Getter
	private final Set<HardwoodPatch> fossilIslandHardwoodPatches = new HashSet<>();

	@Override
	protected void startUp() throws Exception
	{
		overlayManager.add(overlay);
	}

	@Override
	protected void shutDown() throws Exception
	{
		overlayManager.remove(overlay);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged gameStateChanged)
	{
		if (gameStateChanged.getGameState() != GameState.LOADING)
			return;

		fossilIslandHardwoodPatches.clear();
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		final var player = client.getLocalPlayer();
		if (player == null)
		{
			inFossilIslandHardwoodArea = false;
			return;
		}

		final var location = player.getWorldLocation();
		if (location == null)
		{
			inFossilIslandHardwoodArea = false;
			return;
		}

		inFossilIslandHardwoodArea = FOSSIL_ISLAND_HARDWOOD_AREA.contains2D(location);

		for (final var patch : fossilIslandHardwoodPatches)
			patch.onGameTick();
	}

	@Subscribe
	public void onGameObjectSpawned(GameObjectSpawned event)
	{
		final var object = event.getGameObject();
		if (object == null)
			return;

		if (!FOSSIL_ISLAND_HARDWOOD_PATCH_IDS.contains(object.getId()))
			return;

		fossilIslandHardwoodPatches.add(new HardwoodPatch(client, notifier, config, object));
	}

	@Subscribe
	public void onGameObjectDespawned(GameObjectDespawned event)
	{
		final var object = event.getGameObject();
		if (object == null)
			return;

		if (!FOSSIL_ISLAND_HARDWOOD_PATCH_IDS.contains(object.getId()))
			return;

		fossilIslandHardwoodPatches.removeIf(x -> x.getObject() == object);
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (!inFossilIslandHardwoodArea)
			return;

		if (!config.notifyOnFull().isEnabled())
			return;

		if (event.getType() != ChatMessageType.GAMEMESSAGE)
			return;

		if (!event.getMessage().equals(INVENTORY_FULL_MESSAGE))
			return;

		notifier.notify(config.notifyOnFull(), "Inventory is full of mahogany logs.");
	}

	@Provides
	FossilIslandMahoganyTimersConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(FossilIslandMahoganyTimersConfig.class);
	}
}

package org.zhbot.fossil_island_mahogany_timers;

import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.ProgressPieComponent;

import javax.inject.Inject;
import java.awt.*;

public class FossilIslandMahoganyTimersOverlay extends Overlay {
    private final Client client;
    private final FossilIslandMahoganyTimersPlugin plugin;
    private final FossilIslandMahoganyTimersConfig config;

    @Inject
    private FossilIslandMahoganyTimersOverlay(Client client, FossilIslandMahoganyTimersPlugin plugin, FossilIslandMahoganyTimersConfig config)
    {
        this.client = client;
        this.plugin = plugin;
        this.config = config;

        setLayer(OverlayLayer.ABOVE_SCENE);
        setPosition(OverlayPosition.DYNAMIC);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (!plugin.isInFossilIslandHardwoodArea())
            return null;

        final var patches = plugin.getFossilIslandHardwoodPatches();
        if (patches.isEmpty())
            return null;

        final var progressPieComponent = new ProgressPieComponent();
        progressPieComponent.setFill(config.progressColour());
        progressPieComponent.setBorderColor(config.progressColour().darker());

        for (final var patch : patches)
        {
            final var progress = patch.getProgress();
            if (progress < 0)
                continue;

            final var object = patch.getObject();
            final var localPoint = object.getLocalLocation();
            final var point = Perspective.localToCanvas(client, localPoint, object.getPlane(), 0);
            if (point == null)
                continue;

            progressPieComponent.setProgress(progress);
            progressPieComponent.setPosition(point);
            progressPieComponent.render(graphics);
        }

        return null;
    }
}

package org.zhbot.fossil_island_mahogany_timers;

import lombok.Getter;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.ObjectComposition;
import net.runelite.api.gameval.ObjectID;
import net.runelite.client.Notifier;

public class HardwoodPatch {
    private static final long RESPAWN_MILLIS = 40 * 600;

    private final Notifier notifier;
    private final FossilIslandMahoganyTimersConfig config;
    @Getter
    private final GameObject object;

    private final ObjectComposition objectComposition;
    private int lastImposterId = -1;
    private long treeStumpSpawnTime = -1;

    public HardwoodPatch(final Client client, final Notifier notifier, final FossilIslandMahoganyTimersConfig config, final GameObject object)
    {
        this.notifier = notifier;
        this.config = config;
        this.object = object;

        this.objectComposition = client.getObjectDefinition(object.getId());
    }

    public void onGameTick()
    {
        final var imposter = objectComposition.getImpostor();
        if (imposter == null)
        {
            lastImposterId = -1;
            return;
        }

        final var imposterId = imposter.getId();
        if (imposterId == lastImposterId)
            return;

        if (imposterId != ObjectID.MAHOGANY_TREE_STUMP)
        {
            treeStumpSpawnTime = -1;
        }
        else
        {
            treeStumpSpawnTime = System.currentTimeMillis();
            if (lastImposterId == ObjectID.MAHOGANY_TREE_FULLYGROWN)
                notifier.notify(config.notifyOnChop(), "Mahogany tree chopped.");
        }

        lastImposterId = imposterId;
    }

    public double getProgress()
    {
        if (treeStumpSpawnTime == -1)
            return -1;

        final var ms = System.currentTimeMillis() - treeStumpSpawnTime;
        return (double)ms / RESPAWN_MILLIS;
    }
}
